func:
let conectado = msg.status.fill === 'green';
flow.set('estadoConectado', conectado);
return msg;

msg.payload = {
    connected: flow.get('estadoConectado') || false,
    lastUpdate: flow.get('ultimaFecha') || '--:--:--'
};
return msg;

let d = msg.payload;
const gb = 1024 * 1024 * 1024;

if (!d || !d.host || !d.memory || !d.cpu || !d.drive) {
    node.warn("Procesar host: payload incompleto, se ignora");
    return null;
}

let raw = d.host.time;
let match = raw.match(/(\w+) (\d+) (\w+) (\d+):(\d+):(\d+)/);

let meses = { Jan:'ene', Feb:'feb', Mar:'mar', Apr:'abr', May:'may', Jun:'jun', Jul:'jul', Aug:'ago', Sep:'sep', Oct:'oct', Nov:'nov', Dec:'dic' };
let diasSemana = { Mon:'lun', Tue:'mar', Wed:'mié', Thu:'jue', Fri:'vie', Sat:'sáb', Sun:'dom' };

let fechaLegible = match
    ? `${diasSemana[match[1]]} ${match[2]} ${meses[match[3]]}, ${match[4]}:${match[5]}:${match[6]}`
    : raw;

msg.payload = {
    hostname: d.host.hostname,
    address: d.host.address,
    time: d.host.time,
    fechaLegible: fechaLegible,
    diskAvailable: d.drive.disk_available,
    diskUsed: d.drive.disk_used,
    diskTotal: d.drive.disk_total,
    // diskUsage: d.drive.disk_usage,
    diskUsage: parseFloat(d.drive.disk_usage),
    diskUsageText: d.drive.disk_usage,
    // cpuUsage: d.cpu.cpu_usage,
    cpuUsage: parseFloat(d.cpu.cpu_usage),
    cpuTemp: d.cpu.cpu_temp.replace("temp=", "").replace("'C",""),
    cpuTempText: d.cpu.cpu_temp.replace("temp=", "").replace("'C"," °C"),
    // memTotal: d.memory.total_mem,
    memTotal: (d.memory.total_mem/gb).toFixed(2)+"GB",
    // memFree: d.memory.free_mem,
    memFree: (d.memory.free_mem/gb).toFixed(2)+"GB",
    // memUsage: d.memory.mem_usage.toFixed(1),
    memUsage: parseFloat(d.memory.mem_usage.toFixed(1)),
    locationLat: d.location.lat.toFixed(4),
    locationLon: d.location.lon.toFixed(4)
};
return msg;

msg.payload = {
    messageType: msg.payload.messageType,
    input1: msg.payload.input1,
    input2: msg.payload.input2,
    relay1: msg.payload.relay1,
    relay2: msg.payload.relay2,
    relay3: msg.payload.relay3,
    relay4: msg.payload.relay4,
    pwm1: msg.payload.pwm1,
    pwm2: msg.payload.pwm2,
    pwm3: msg.payload.pwm3,
    date: msg.payload.date
};
flow.set('estadoIO', msg.payload);
return msg;

msg.payload = {
    key: msg.payload.type,   // "relay" o "pwm"
    id: msg.payload.id,      // "1" a "4" (relay) o "1" a "2" (pwm)
    value: msg.payload.value // 1/0 para relay, 0-255 para pwm
};
msg.topic = "isil/stations/001/commands";
return msg;

let d = msg.payload;
let data = d.speedtest;

if (!d || !data) {
    node.warn("Procesar host: payload incompleto, se ignora");
    return null;
}

msg.payload = {
    ping: data.ping,
    download: data.download,
    upload: data.upload
}
return msg;
